    INSERT INTO mcqs (topic_id, question, options, correct_index, explanation) VALUES
    (v_topic_id, '101: Which of the following is the most common cause of "congenital hypothyroidism" worldwide?', '["Autoimmune thyroiditis", "Iodine deficiency", "Thyroid dysgenesis", "Pituitary failure"]', 1, 'In iodine-replete areas, thyroid dysgenesis is most common, but globally, iodine deficiency leads.'),
    (v_topic_id, '102: "Scaphocephaly" (long, narrow head) is caused by the premature closure of which suture?', '["Coronal", "Sagittal", "Lambdoid", "Metopic"]', 1, 'Sagittal synostosis is the most common form of craniosynostosis.'),
    (v_topic_id, '103: "Trigonocephaly" (triangular-shaped forehead) is caused by the premature closure of the:', '["Sagittal suture", "Metopic suture", "Coronal suture", "Squamosal suture"]', 1, 'Metopic synostosis results in a ridge down the forehead.'),
    (v_topic_id, '104: A child with "Apert Syndrome" will have craniosynostosis and what other classic feature?', '["Polydactyly", "Syndactyly (mitten-hand deformity)", "Radial dysplasia", "Clubfoot"]', 1, 'Apert syndrome involves mutations in FGFR2 and complex syndactyly of hands and feet.'),
    (v_topic_id, '105: Which syndrome is characterized by "tower skull" (turricephaly), midface hypoplasia, and proptosis, but NO hand/foot anomalies?', '["Apert Syndrome", "Crouzon Syndrome", "Pfeiffer Syndrome", "Carpenter Syndrome"]', 1, 'Crouzon is another FGFR2-related craniosynostosis syndrome without limb defects.'),
    (v_topic_id, '106: "Amniotic band sequence" can lead to:', '["Cleft palate", "Limb amputations and ring constrictions", "VSD", "Renal agenesis"]', 1, 'Fibrous bands from the amnion can entrap and constrict fetal parts.'),
    (v_topic_id, '107: A child with "Treacher Collins Syndrome" will primarily have anomalies of which structures?', '["Heart and Lungs", "First and second branchial arches (craniofacial)", "Limbs", "Kidneys"]', 1, 'Features include malar hypoplasia, coloboma of lower eyelids, and ear malformations.'),
    (v_topic_id, '108: Which syndrome is characterized by "micrognathia," "glossoptosis," and "respiratory obstruction" due to the tongue falling back?', '["Pierre Robin Sequence", "Goldenhar Syndrome", "Noonan Syndrome", "DiGeorge Syndrome"]', 0, 'The U-shaped cleft palate is a secondary feature of the sequence.'),
    (v_topic_id, '109: "Goldenhar Syndrome" (Oculo-auriculo-vertebral dysplasia) is often characterized by:', '["Bilateral facial defects", "Unilateral facial hypoplasia, preauricular tags, and epibulbar dermoids", "Macroglossia", "Polydactyly"]', 1, 'It is a hemifacial microsomia with eye and vertebral involvement.'),
    (v_topic_id, '110: A neonate has "choanal atresia" (blockage of the posterior nasal passages). What is the first sign?', '["Stridor", "Cyanosis that improves with crying", "Excessive drooling", "Choking with feeds only"]', 1, 'Infants are obligate nasal breathers; crying allows oral breathing and relieves cyanosis.'),
    (v_topic_id, '111: Which congenital anomaly is associated with "maternal diabetes" (specifically poorly controlled)?', '["Caudal regression syndrome", "Hypertrophic cardiomyopathy", "Transposition of the Great Arteries", "All of the above"]', 3, 'Infants of diabetic mothers have higher rates of various structural defects.'),
    (v_topic_id, '112: "Caudal regression syndrome" (sacral agenesis) is highly specific for exposure to:', '["Alcohol", "Maternal diabetes", "Phenytoin", "Smoking"]', 1, 'While rare, it is strongly linked to pre-gestational diabetes.'),
    (v_topic_id, '113: A child with "Smith-Lemli-Opitz Syndrome" has a defect in which metabolic pathway?', '["Urea cycle", "Cholesterol biosynthesis", "Gluconeogenesis", "Fatty acid oxidation"]', 1, 'Deficiency of 7-dehydrocholesterol reductase leads to low cholesterol and multiple anomalies.'),
    (v_topic_id, '114: Classically, Smith-Lemli-Opitz presents with syndactyly of which toes?', '["1st and 2nd", "2nd and 3rd", "4th and 5th", "None"]', 1, 'Y-shaped syndactyly of the 2nd and 3rd toes is a characteristic finding.'),
    (v_topic_id, '115: "Russell-Silver Syndrome" is characterized by:', '["Intrauterine growth restriction (IUGR), triangular facies, and limb asymmetry", "Severe obesity", "Macrocephaly", "Limb overgrowth"]', 0, 'It is an imprinting disorder with primordial dwarfism features.'),
    (v_topic_id, '116: "Sotos Syndrome" is also known as:', '["Cerebral gigantism", "Bird-headed dwarfism", "Brittle bone disease", "Frog-leg syndrome"]', 0, 'Characterized by overgrowth, macrocephaly, and developmental delay.'),
    (v_topic_id, '117: Which metabolic disorder presents with "sweaty feet" odor?', '["PKU", "Isovaleric Acidemia", "Tyrosinemia", "MSUD"]', 1, 'Organic acidemias often have distinct odors.'),
    (v_topic_id, '118: A child with "Tyrosinemia Type 1" is at extremely high risk for which cancer?', '["Leukemia", "Hepatocellular carcinoma", "Wilms tumor", "Osteosarcoma"]', 1, 'Accumulation of fumarylacetoacetate leads to severe liver damage and malignancy.'),
    (v_topic_id, '119: What is the odor associated with "Trimethylaminuria"?', '["Mousy", "Sweaty feet", "Rotting fish", "Boiled cabbage"]', 2, 'The inability to break down trimethylamine leads to a fishy smell.'),
    (v_topic_id, '120: "Alkaptonuria" is characterized by urine that:', '["Smells like maple syrup", "Turns black when exposed to air", "Is bright red", "Is colorless"]', 1, 'Homogentisic acid oxidase deficiency leads to ochronosis and arthritis later in life.'),
    (v_topic_id, '121: Which inborn error of metabolism presents with "hyperammonemia" but NO acidosis or ketosis?', '["Organic acidemia", "Urea cycle defect", "Glycogen storage disease", "Galactosemia"]', 1, 'Urea cycle defects (like OTC deficiency) present with pure ammonia elevation.'),
    (v_topic_id, '122: What is the most common "Urea Cycle Defect"?', '["Ornithine transcarbamylase (OTC) deficiency", "Argininosuccinic aciduria", "Citrullinemia", "Carbamoyl phosphate synthetase I deficiency"]', 0, 'OTC deficiency is uniquely X-linked recessive, while the others are autosomal recessive.'),
    (v_topic_id, '123: A male infant with hyperammonemia and "low citrulline" and "high orotic acid" likely has:', '["CPS1 deficiency", "OTC deficiency", "Propionic acidemia", "MSUD"]', 1, 'High orotic acid distinguishes OTC from CPS1 deficiency.'),
    (v_topic_id, '124: "Biotinidase deficiency" can cause:', '["Seizures, hearing loss, and skin rash", "Obesity", "Cataracts", "Limb defects"]', 0, 'Easily treated with biotin supplementation if caught early.'),
    (v_topic_id, '125: Which condition is caused by a defect in "peroxisome" biogenesis?', '["Zellweger Syndrome", "Pompe Disease", "Hurler Syndrome", "Gaucher Disease"]', 0, 'Zellweger is the most severe peroxisomal disorder, causing hypotonia and hepatomegaly.'),
    (v_topic_id, '126: "Adrenoleukodystrophy" (X-linked) leads to the accumulation of:', '["Branched-chain amino acids", "Very-long-chain fatty acids (VLCFA)", "Glycogen", "Copper"]', 1, 'Leads to progressive neurological decline and adrenal insufficiency.'),
    (v_topic_id, '127: A child with "Wilson Disease" has a defect in the excretion of:', '["Iron", "Copper", "Zinc", "Magnesium"]', 1, 'Copper accumulates in the liver, brain (basal ganglia), and eyes (Kayser-Fleischer rings).'),
    (v_topic_id, '128: What is the characteristic finding in "Menkes Disease" (Steely Hair Syndrome)?', '["Sparse, kinky, brittle hair", "Excessive body hair", "White forelock", "Alopecia"]', 0, 'Menkes is a defect in copper absorption/transport, leading to low serum copper.'),
    (v_topic_id, '129: "Lesch-Nyhan Syndrome" is characterized by "self-mutilation" and hyperuricemia due to a defect in:', '["HPRT1 (Salvage pathway)", "De novo purine synthesis", "Pyrimidine synthesis", "Urea cycle"]', 0, 'X-linked recessive disorder with gout and neurological symptoms.'),
    (v_topic_id, '130: A 1-year-old child with "Gaucher Disease Type 1" (the non-neuronopathic form) classically presents with:', '["Cataracts", "Hepatosplenomegaly and bone pain (Erlenmeyer flask deformity)", "Heart failure", "Hydrocephalus"]', 1, 'Most common lysosomal storage disease; involves glucocerebrosidase deficiency.'),
    (v_topic_id, '131: "Fabry Disease" is an X-linked lysosomal storage disease characterized by:', '["Hepatosplenomegaly", "Angiokeratomas, peripheral neuropathy, and renal failure", "Cherry-red spot", "Coarse facies"]', 1, 'Deficiency of alpha-galactosidase A.'),
    (v_topic_id, '132: "Krabbe Disease" is a leukodystrophy caused by deficiency of:', '["Galactocerebrosidase", "Arylsulfatase A", "Sphingomyelinase", "Acid maltase"]', 0, 'Causes destruction of myelin in the CNS and PNS.'),
    (v_topic_id, '133: "Metachromatic leukodystrophy" is caused by deficiency of:', '["Arylsulfatase A", "Hexosaminidase A", "Glucocerebrosidase", "Iduronate sulfatase"]', 0, 'Leads to accumulation of sulfatides and demyelination.'),
    (v_topic_id, '134: A child with "Cystinosis" (accumulation of cystine in lysosomes) classically develops:', '["Renal Fanconi Syndrome", "Hypertrophic cardiomyopathy", "Liver failure", "Macro-orchidism"]', 0, 'Presents with polyuria, polydipsia, and growth failure.'),
    (v_topic_id, '135: What is the inheritance pattern of "Achondroplasia"?', '["Autosomal Recessive", "Autosomal Dominant", "X-linked Recessive", "Mitochondrial"]', 1, 'Though most cases are new mutations, it is inherited in a dominant fashion.'),
    (v_topic_id, '136: If two parents with "Achondroplasia" have a child, what is the risk of the child having "lethal" homozygous achondroplasia?', '["25%", "50%", "75%", "100%"]', 0, 'AA is lethal; Aa has achondroplasia; aa is average height.'),
    (v_topic_id, '137: "Cornelia de Lange Syndrome" is characterized by:', '["Tall stature", "Synophrys (joined eyebrows), long eyelashes, and limb reduction defects", "Friendliness", "Macroglossia"]', 1, 'Also includes growth retardation and severe intellectual disability.'),
    (v_topic_id, '138: "Stickler Syndrome" involves mutations in collagen and often presents with:', '["Pierre Robin sequence, severe myopia, and hearing loss", "Macrocephaly", "Polydactyly", "Eczema"]', 0, 'It is a common cause of syndromic cleft palate.'),
    (v_topic_id, '139: Which condition is characterized by "asymmetric" limb growth and "overgrowth" of various tissues (Proteus Syndrome)?', '["Elephantiasis", "Mosaic AKT1 mutation", "Trisomy 21", "NF2"]', 1, 'Proteus is an overgrowth syndrome (famously associated with the Elephant Man).'),
    (v_topic_id, '140: A child with "Poland Syndrome" has:', '["Absence of the pectoralis major muscle and ipsilateral syndactyly", "Bilateral absence of kidneys", "Macroglossia", "Short stature"]', 0, 'Likely due to a vascular disruption during development.'),
    (v_topic_id, '141: "Mobius Syndrome" is characterized by the absence or hypoplasia of which cranial nerves?', '["I and II", "VI and VII", "IX and X", "XI and XII"]', 1, 'Leads to a mask-like face and inability to abduct the eyes.'),
    (v_topic_id, '142: "Holt-Oram Syndrome" (Heart-Hand Syndrome) includes:', '["ASD/VSD and radial limb defects (e.g., triphalangeal thumb)", "Cardiomyopathy and cataracts", "Coarctation and webbed neck", "Truncus arteriosus and thymic hypoplasia"]', 0, 'Autosomal dominant mutation in TBX5.'),
    (v_topic_id, '143: "TAR Syndrome" stands for Thrombocytopenia with:', '["Absent Radius", "Absent Ribs", "Absent Retina", "Absent Renal function"]', 0, 'Unlike Holt-Oram and Fanconi Anemia, the THUMBS ARE PRESENT in TAR.'),
    (v_topic_id, '144: "Fanconi Anemia" is an AR disorder of DNA repair presenting with:', '["Aplastic anemia and radial hypoplasia (absent thumbs)", "Microcephaly", "Café-au-lait spots", "All of the above"]', 3, 'Increases risk for AML and other cancers.'),
    (v_topic_id, '145: Which "association" includes Vertebral, Anal, Cardiac, TE fistula, Renal, and Limb defects?', '["CHARGE", "VACTERL", "MURCS", "PHACE"]', 1, 'VACTERL association is a non-random group of malformations.'),
    (v_topic_id, '146: "Anencephaly" results from failure of closure of the:', '["Posterior neuropore", "Anterior neuropore", "Midgut", "Pleuroperitoneal folds"]', 1, 'Occurs at ~24 days of gestation.'),
    (v_topic_id, '147: Which maternal factor is associated with the highest risk of "sacral agenesis" in the fetus?', '["Smoking", "Insulin-dependent diabetes mellitus", "Folic acid intake", "Alcohol use"]', 1, 'This is a classic association in pediatric boards.'),
    (v_topic_id, '148: A neonate has "bilateral colobomas" of the iris. Which syndrome should be considered first?', '["VACTERL", "CHARGE", "Down", "Turner"]', 1, 'Coloboma is the "C" in CHARGE.'),
    (v_topic_id, '149: "Choanal atresia" is the most common cause of nasal obstruction in neonates. It is the "A" in:', '["CHARGE", "VACTERL", "PHACE", "MURCS"]', 0, 'Choanal atresia is a major feature of CHARGE.'),
    (v_topic_id, '150: "Eagle-Barrett" syndrome is also known as:', '["Prune Belly Syndrome", "Potter Sequence", "Pierre Robin Sequence", "Beckwith-Wiedemann"]', 0, 'Characterized by wrinkled abdominal skin due to lack of musculature.'),
    (v_topic_id, '151: What is the most common "extracranial" solid tumor of childhood, often associated with congenital anomalies?', '["Wilms Tumor", "Neuroblastoma", "Hepatoblastoma", "Rhabdomyosarcoma"]', 1, 'Neuroblastoma can arise from the adrenal gland or sympathetic chain.'),
    (v_topic_id, '152: "WAGR Syndrome" includes Wilms tumor, Aniridia, Genitourinary anomalies, and:', '["Retardation (Intellectual)", "Radial defects", "Retinitis", "Rubella"]', 0, 'Caused by a deletion on chromosome 11 (WT1 and PAX6 genes).'),
    (v_topic_id, '153: "Aniridia" (absence of the iris) should always prompt screening for:', '["Heart defects", "Wilms tumor", "Liver failure", "Cataracts"]', 1, 'PAX6 deletion often includes the nearby WT1 gene.'),
    (v_topic_id, '154: Which condition is characterized by "hemihyperplasia" (one side of the body larger than the other)?', '["Beckwith-Wiedemann Syndrome", "Down Syndrome", "Turner Syndrome", "Klinefelter Syndrome"]', 0, 'Classically seen in BWS and Proteus syndrome.'),
    (v_topic_id, '155: A neonate has a "midline" scalp defect (Aplasia Cutis Congenita). This is a marker for:', '["Trisomy 21", "Trisomy 13", "Trisomy 18", "Turner Syndrome"]', 1, 'Aplasia cutis congenita on the vertex is a classic sign of Patau syndrome.'),
    (v_topic_id, '156: "Coloboma" of the lower eyelid is characteristic of:', '["Treacher Collins Syndrome", "CHARGE Syndrome", "Goldenhar Syndrome", "Noonan Syndrome"]', 0, 'Distinguishes it from iris coloboma seen in CHARGE.'),
    (v_topic_id, '157: "Hypoplasia of the depressor anguli oris muscle" leads to:', '["Asymmetric crying facies", "Mask-like face", "Drooling", "Cleft lip"]', 0, 'When the child cries, the mouth is pulled to the normal side; can be associated with 22q11 deletion.'),
    (v_topic_id, '158: "Lissencephaly" (smooth brain) is characterized by:', '["Absence of gyri and sulci", "Excessive gyri", "Fluid-filled brain", "Failure of the midline to divide"]', 0, 'Type 1 (Miller-Dieker) is associated with 17p13.3 deletion.'),
    (v_topic_id, '159: "Miller-Dieker Syndrome" includes lissencephaly and:', '["Severe intellectual disability and characteristic facies (short nose, upturned nares)", "Polydactyly", "Heart defects", "Normal intelligence"]', 0, 'A severe neurodevelopmental syndrome.'),
    (v_topic_id, '160: A child with "Walker-Warburg Syndrome" has lissencephaly, eye anomalies, and:', '["Congenital muscular dystrophy", "Hepatomegaly", "Renal cysts", "Limb defects"]', 0, 'A lethal autosomal recessive disorder.'),
    (v_topic_id, '161: "Dandy-Walker Malformation" consists of:', '["Agenesis of the cerebellar vermis and cystic dilation of the 4th ventricle", "Herniation of cerebellar tonsils", "Absence of the corpus callosum", "Fusion of the hemispheres"]', 0, 'Often results in hydrocephalus.'),
    (v_topic_id, '162: "Chiari I Malformation" is the downward displacement of the:', '["Cerebellar tonsils", "Cerebellar vermis and medulla", "Brainstem only", "Frontal lobes"]', 0, 'Usually asymptomatic until adolescence/adulthood; may cause syrinx.'),
    (v_topic_id, '163: "Chiari II Malformation" involves displacement of the vermis, tonsils, and medulla, and is associated with:', '["Myelomeningocele", "Dandy-Walker", "Holoprosencephaly", "Microcephaly"]', 0, 'Nearly all infants with myelomeningocele have Chiari II.'),
    (v_topic_id, '164: "Lumbosacral hair tuft" or "sacral dimple" (deep) should be evaluated for:', '["Spina bifida occulta or tethered cord", "Meningitis", "Constipation", "Normal finding only"]', 0, 'Ultrasound or MRI is used to screen for underlying spinal dysraphism.'),
    (v_topic_id, '165: "Encephalocele" is most commonly found in which location in Western populations?', '["Frontal", "Occipital", "Parietal", "Nasal"]', 1, 'Protrusion of brain and/or meninges through a skull defect.'),
    (v_topic_id, '166: A child has "congenital miosis," "ptosis," and "anhidrosis" (Horner Syndrome). What is a common "congenital" cause?', '["Brachial plexus injury (Klumpke palsy)", "Neuroblastoma", "Carotid dissection", "Both A and B"]', 3, 'Lower brachial plexus injuries and mediastinal tumors can affect the sympathetic chain.'),
    (v_topic_id, '167: "Heterochromia iridis" (different colored eyes) can be seen in:', '["Waardenburg Syndrome", "Congenital Horner Syndrome", "Sturge-Weber", "All of the above"]', 3, 'Various conditions can affect iris pigmentation.'),
    (v_topic_id, '168: "Brushfield spots" are small, white-grey spots on the iris found in:', '["Down Syndrome", "Normal infants", "Trisomy 18", "Both A and B"]', 3, 'They are more common in Down syndrome but can be found in some normal individuals.'),
    (v_topic_id, '169: "Peters Anomaly" is a congenital defect of the:', '["Cornea (central opacity)", "Lens", "Retina", "Optic nerve"]', 0, 'Part of the anterior segment dysgenesis group.'),
    (v_topic_id, '170: "Microphthalmia" (small eyes) is a major feature of:', '["Trisomy 13", "Fetal Alcohol Syndrome", "Congenital Rubella", "All of the above"]', 3, 'Multiple conditions can result in small or absent (anophthalmia) eyes.'),
    (v_topic_id, '171: "Preauricular tags and pits" are common. If they are the ONLY finding in an otherwise healthy infant, what is the risk of renal anomalies?', '["High (require routine ultrasound)", "Low (no routine screening needed)", "100%", "Zero"]', 1, 'Isolated preauricular anomalies do NOT require renal ultrasound unless other risk factors exist.'),
    (v_topic_id, '172: "Microtia" (small ear) and "anotia" (absent ear) are frequently associated with:', '["Treacher Collins and Goldenhar syndromes", "Down syndrome", "Turner syndrome", "Klinefelter syndrome"]', 0, 'Derived from the 1st and 2nd branchial arches.'),
    (v_topic_id, '173: "Cleft lip" occurs due to failure of fusion of the:', '["Maxillary and medial nasal processes", "Lateral nasal processes", "Palatine shelves", "Frontonasal process only"]', 0, 'Occurs between 5th and 8th week of gestation.'),
    (v_topic_id, '174: "Cleft palate" occurs due to failure of fusion of the:', '["Palatine shelves", "Maxillary processes", "Mandibular processes", "Premaxilla"]', 0, 'Can occur with or without cleft lip; different embryological timing.'),
    (v_topic_id, '175: "Bifid uvula" is often a marker for:', '["Submucous cleft palate", "Dental caries", "Pierre Robin", "Normal finding only"]', 0, 'A submucous cleft should be suspected if there is bifid uvula and nasal regurgitation.'),
    (v_topic_id, '176: "Thyroglossal duct cyst" is a "midline" neck mass that moves with:', '["Swallowing", "Tongue protrusion", "Coughing", "Both A and B"]', 3, 'It is an embryological remnant of thyroid migration.'),
    (v_topic_id, '177: "Branchial cleft cysts" are typically found in which location?', '["Midline neck", "Lateral neck (anterior to sternocleidomastoid)", "Posterior neck", "Vertex of scalp"]', 1, 'Derived from the branchial apparatus; 2nd cleft is most common.'),
    (v_topic_id, '178: "Cystic hygroma" (lymphangioma) is most commonly associated with which syndrome?', '["Turner Syndrome", "Down Syndrome", "Noonan Syndrome", "All of the above"]', 3, 'Often found in the neck (posterior triangle).'),
    (v_topic_id, '179: A neonate has a "sacrococcygeal teratoma." What is the most important management?', '["Immediate surgical excision", "Observation", "Chemotherapy only", "Wait until 1 year"]', 0, 'Most are benign but have a risk of malignant transformation if not removed.'),
    (v_topic_id, '180: "Bladder exstrophy" is more common in:', '["Males", "Females", "Equal", "None"]', 0, 'Associated with a low-set umbilicus and bifid clitoris/penis.'),
    (v_topic_id, '181: "Epispadias" in males is often associated with:', '["Incontinence", "Cryptorchidism", "Inguinal hernia", "Normal function"]', 0, 'Urethral opening on the dorsal surface of the penis.'),
    (v_topic_id, '182: "Hypospadias" is often associated with "chordee." What is chordee?', '["Ventral curvature of the penis", "Dorsal curvature", "Rotation of the penis", "Small penis size"]', 0, 'Often corrected during hypospadias repair.'),
    (v_topic_id, '183: "Cryptorchidism" (undescended testis) should be surgically corrected (orchiopexy) by what age?', '["6 months to 1 year", "3 years", "5 years", "Puberty"]', 0, 'Early correction reduces the risk of torsion and improves fertility potential (though cancer risk remains).'),
    (v_topic_id, '184: A child with "bilateral" cryptorchidism and hypospadias must be evaluated for:', '["Disorders of Sexual Development (DSD) and CAH", "Renal failure", "Bladder exstrophy", "None"]', 0, 'This combination is a high-risk indicator for an underlying DSD.'),
    (v_topic_id, '185: "Posterior Urethral Valves (PUV)" is the most common cause of "obstructive uropathy" in:', '["Male infants", "Female infants", "Adolescents", "Adults"]', 0, 'Can lead to prune belly syndrome and renal failure in utero.'),
    (v_topic_id, '186: "Multicystic Dysplastic Kidney (MCDK)" is usually:', '["Unilateral and non-functional", "Bilateral and lethal", "Cystic but functional", "A precursor to cancer"]', 0, 'The most common cause of an abdominal mass in a neonate.'),
    (v_topic_id, '187: "Autosomal Recessive Polycystic Kidney Disease (ARPKD)" classically presents with:', '["Bilateral large echogenic kidneys and liver fibrosis", "Unilateral cysts", "Normal kidney size", "Hypertension only"]', 0, 'Often associated with Potter sequence if severe in utero.'),
    (v_topic_id, '188: "Clubfoot" (Talipes Equinovarus) involves which four deformities?', '["Inversion, Adduction, Equinus, and Cavus", "Eversion, Abduction, Calcaneus, and Flat foot", "Flexion, Extension, Pronation, Supination", "None"]', 0, 'Treated with the Ponseti method (serial casting).'),
    (v_topic_id, '189: "Developmental Dysplasia of the Hip (DDH)" is more common in infants who are:', '["First-born, female, and breech presentation", "Male and vertex", "Premature", "Second-born"]', 0, 'Barlow and Ortolani maneuvers are used for screening.'),
    (v_topic_id, '190: What is the preferred imaging modality for DDH in an infant <4-6 months?', '["X-ray", "Ultrasound", "MRI", "CT"]', 1, 'The femoral head is not yet ossified, making X-ray less useful.'),
    (v_topic_id, '191: "Polydactyly" on the "pinky" side is called:', '["Post-axial", "Pre-axial", "Meso-axial", "None"]', 0, 'Post-axial is common and often isolated; pre-axial (thumb side) is more often syndromic.'),
    (v_topic_id, '192: "Syndactyly" refers to:', '["Extra fingers", "Webbed or fused fingers", "Short fingers", "Bent fingers"]', 1, 'Most common in the hand between the 3rd and 4th digits.'),
    (v_topic_id, '193: "Radial ray defects" (absent or hypoplastic radius/thumb) are associated with:', '["Fanconi Anemia, Holt-Oram, and VACTERL", "Down Syndrome", "Turner Syndrome", "None"]', 0, 'A crucial clinical clue for multi-system syndromes.'),
    (v_topic_id, '194: "Clinodactyly" (curved 5th finger) is a common minor anomaly in:', '["Down Syndrome", "Turner Syndrome", "Normal individuals", "All of the above"]', 3, 'While a marker for Down syndrome, it is seen in ~1-2% of the general population.'),
    (v_topic_id, '195: "Sandal gap" (increased space between the 1st and 2nd toes) is a marker for:', '["Down Syndrome", "Noonan Syndrome", "Trisomy 13", "Trisomy 18"]', 0, 'One of the many minor physical signs of Trisomy 21.'),
    (v_topic_id, '196: "Single transverse palmar crease" (Simian crease) is found in:', '["Down Syndrome", "5% of the normal population", "Turner Syndrome", "Both A and B"]', 3, 'Highly associated with Down syndrome but not pathognomonic.'),
    (v_topic_id, '197: "Mitochondrial inheritance" disorders (like MELAS) are passed from:', '["Mother to all children", "Father to all children", "Mother to sons only", "Father to daughters only"]', 0, 'Sperm do not contribute mitochondria to the zygote.'),
    (v_topic_id, '198: "Uniparental Disomy (UPD)" refers to:', '["Two chromosomes from one parent, none from the other", "One chromosome from each parent", "An extra chromosome", "A missing chromosome"]', 0, 'Mechanism for Prader-Willi and Angelman if no deletion is present.'),
    (v_topic_id, '199: "Mosaicism" occurs when:', '["Two or more cell lines with different genotypes exist in one individual", "All cells have the same mutation", "A mutation is only in the sperm", "A mutation is only in the egg"]', 0, 'Can lead to a milder phenotype of a syndrome (e.g., Mosaic Down Syndrome).'),
    (v_topic_id, '200: "Germline mosaicism" explains why:', '["Healthy parents can have multiple children with the same autosomal dominant disorder", "A child can have a milder disease", "A disorder skips a generation", "None"]', 0, 'The mutation is present in a subset of germ cells but not in the parent''s somatic cells.');
